function imageSettings({ spreadsheet, tab, folder, origin }) {
  if (
    !/^[A-Za-z0-9_-]{8,}$/.test(spreadsheet) ||
    !tab.trim() ||
    !/^[A-Za-z0-9_-]{8,}$/.test(folder) ||
    [spreadsheet, folder].some((id) => id.startsWith("YOUR_"))
  ) {
    throw Error("Configure the spreadsheet ID, sheet tab, and Drive folder ID.");
  }
  if (
    !/^https:\/\/(?:[a-z0-9-]+\.)+[a-z]{2,63}$/.test(origin) ||
    /\.(?:invalid|local|localhost)$/.test(origin)
  ) {
    throw Error("Set the exact HTTPS origin for your signed ApyHub download links.");
  }
  const prefix = "'" + tab.replaceAll("'", "''") + "'!";
  return { spreadsheet, folder, origin, prefix, range: prefix + "A1:C" };
}
export default (inputs) => {
  const config = imageSettings(inputs);
  return { config, spreadsheet: config.spreadsheet, range: config.range };
};

