function firstImage(values, config) {
  if (!Array.isArray(values) || ["FROM", "TO", "DONE"].some((cell, i) => values[0]?.[i] !== cell)) {
    throw Error("Expected FROM, TO, and DONE in columns A, B, and C.");
  }
  const index = values.findIndex(
    (row, i) => i > 0 && (row[2] === undefined || row[2] === null || row[2] === ""),
  );
  if (index < 0) return null;
  const raw = values[index][0];
  if (typeof raw !== "string" || !raw.trim()) return null;
  const image = raw.trim();
  const path = /^https:\/\/(?:[a-z0-9-]+\.)+[a-z]{2,63}(\/[^\s?#]+)(?:[?#][^\s]*)?$/i.exec(image);
  if (!path) return null;
  let tail;
  try {
    tail = decodeURIComponent(path[1].split("/").at(-1));
  } catch {
    return null;
  }
  const match = /^([^/\\\u0000-\u001f]{1,180})\.(jpg|jpeg|png)$/i.exec(tail);
  if (!match) return null;
  const format = match[2].toLowerCase() === "png" ? "png" : "jpeg";
  const row = index + 1;
  const filename = match[1] + ".webp";
  const endpoint =
    "https://api.eu.apyhub.com/apyhub/convert-" +
    format +
    "-to-webp/url/link?output=" +
    encodeURIComponent(filename);
  return { source: image, filename, row, range: config.prefix + "B" + row + ":C" + row, endpoint };
}
export default ({ values, config }) => {
  const job = firstImage(values, config);
  return {
    job,
    hasImage: Boolean(job),
    endpoint: job?.endpoint ?? "",
    request: job ? { url: job.source } : {},
  };
};

