function resultLink(result, config) {
  if (typeof result?.data !== "string") throw Error("ApyHub did not return a signed WebP URL.");
  if (!result.data.startsWith(config.origin + "/") || /[\s#\\]/.test(result.data))
    throw Error("ApyHub returned an unapproved download origin.");
  return result.data;
}
export default ({ body, config }) => ({ url: resultLink(body, config) });

