function checkWebP(bytes, mime, status) {
  const contentType = String(mime).split(";")[0].trim().toLowerCase();
  const stringAt = (offset) => String.fromCharCode(...bytes.subarray(offset, offset + 4));
  const riffLength = bytes[4] + bytes[5] * 256 + bytes[6] * 65536 + bytes[7] * 16777216;
  if (
    status !== 200 ||
    !["image/webp", "application/octet-stream"].includes(contentType) ||
    bytes.length < 20 ||
    bytes.length > 2 * 1024 * 1024 ||
    stringAt(0) !== "RIFF" ||
    stringAt(8) !== "WEBP" ||
    !["VP8 ", "VP8L", "VP8X"].includes(stringAt(12)) ||
    riffLength + 8 !== bytes.length
  ) {
    throw Error("The download is not a complete WebP of up to 2 MiB.");
  }
}
export default async ({ file, status, job, config }, context) => {
  if (file.size > 2 * 1024 * 1024) throw Error("WebP exceeds the 2 MiB limit.");
  const bytes = await context.artifact.open(file);
  if (bytes.length !== file.size) throw Error("The WebP download is incomplete.");
  checkWebP(bytes, file.mediaType, status);
  let contentBase64 = "";
  for (let offset = 0; offset < bytes.length; offset += 12288) {
    contentBase64 += btoa(String.fromCharCode(...bytes.subarray(offset, offset + 12288)));
  }
  return { name: job.filename, contentBase64, parents: [config.folder] };
};

