function updateRow(file, job, link) {
  if (typeof file.id !== "string" || !file.id || file.name !== job.filename)
    throw Error("Drive did not confirm the selected WebP upload.");
  return { range: job.range, values: [[link, "x"]], fileId: file.id, row: job.row };
}
export default ({ id, name, job, link, spreadsheet }) => {
  const update = updateRow({ id, name }, job, link);
  return { update: { ...update, spreadsheet }, range: update.range, values: update.values };
};

